// ─── Tool Functions ─────────────────────────────────────────────────────────

function parseNum(v) {
  const n = parseFloat(v);
  return isNaN(n) ? null : n;
}

function matchStr(val, filter) {
  if (!filter) return true;
  if (!val) return false;
  return val.toLowerCase().includes(filter.toLowerCase());
}

function filterDeals(filters = {}) {
  let rows = [...DEALS_RAW];
  if (filters.sector) rows = rows.filter(r => matchStr(r["Sector/service"], filters.sector));
  if (filters.status) rows = rows.filter(r => matchStr(r["Deal Status"], filters.status));
  if (filters.stage) rows = rows.filter(r => matchStr(r["Deal Stage"], filters.stage));
  if (filters.owner) rows = rows.filter(r => matchStr(r["Owner code"], filters.owner));
  if (filters.product) rows = rows.filter(r => matchStr(r["Product deal"], filters.product));
  if (filters.deal_name) rows = rows.filter(r => matchStr(r["Deal Name"], filters.deal_name));
  if (filters.date_from) rows = rows.filter(r => r["Created Date"] && r["Created Date"] >= filters.date_from);
  if (filters.date_to) rows = rows.filter(r => r["Created Date"] && r["Created Date"] <= filters.date_to);
  if (filters.tentative_close_from) rows = rows.filter(r => r["Tentative Close Date"] && r["Tentative Close Date"] >= filters.tentative_close_from);
  if (filters.tentative_close_to) rows = rows.filter(r => r["Tentative Close Date"] && r["Tentative Close Date"] <= filters.tentative_close_to);
  return rows;
}

function filterWOs(filters = {}) {
  let rows = [...WO_RAW];
  if (filters.sector) rows = rows.filter(r => matchStr(r["Sector"], filters.sector));
  if (filters.execution_status) rows = rows.filter(r => matchStr(r["Execution Status"], filters.execution_status));
  if (filters.wo_status) rows = rows.filter(r => matchStr(r["WO Status (billed)"], filters.wo_status));
  if (filters.nature) rows = rows.filter(r => matchStr(r["Nature of Work"], filters.nature));
  if (filters.type_of_work) rows = rows.filter(r => matchStr(r["Type of Work"], filters.type_of_work));
  if (filters.owner) rows = rows.filter(r => matchStr(r["BD/KAM Personnel code"], filters.owner));
  if (filters.customer) rows = rows.filter(r => matchStr(r["Customer Name Code"], filters.customer));
  if (filters.deal_name) rows = rows.filter(r => matchStr(r["Deal name masked"], filters.deal_name));
  if (filters.collection_status) rows = rows.filter(r => matchStr(r["Collection status"], filters.collection_status));
  return rows;
}

function aggregateField(rows, groupBy, valueField) {
  const groups = {};
  rows.forEach(r => {
    const key = r[groupBy] || "Unknown/Missing";
    if (!groups[key]) groups[key] = { count: 0, total: 0, values: [] };
    groups[key].count++;
    const v = parseNum(r[valueField]);
    if (v !== null) { groups[key].total += v; groups[key].values.push(v); }
  });
  return Object.entries(groups).map(([k, v]) => ({
    group: k, count: v.count,
    total: Math.round(v.total),
    avg: v.values.length ? Math.round(v.total / v.values.length) : null,
    non_null_count: v.values.length
  })).sort((a, b) => b.total - a.total);
}

function queryDealsBoard(input) {
  const rows = filterDeals(input.filters || {});
  const limit = input.limit || 50;
  const fields = input.fields || ["Deal Name", "Deal Status", "Deal Stage", "Sector/service", "Masked Deal value", "Tentative Close Date", "Owner code", "Closure Probability"];
  const result = rows.slice(0, limit).map(r => {
    const out = {};
    fields.forEach(f => { if (r[f] !== undefined) out[f] = r[f]; });
    return out;
  });
  const totalValue = rows.reduce((s, r) => { const v = parseNum(r["Masked Deal value"]); return v ? s + v : s; }, 0);
  return { total_rows: rows.length, returned: result.length, total_value_excl_null: Math.round(totalValue), rows: result, data_quality: { null_values: rows.filter(r => !r["Masked Deal value"]).length, note: "Deal values are masked/scaled; null values exist for " + rows.filter(r => !r["Masked Deal value"]).length + " of " + rows.length + " rows" } };
}

function queryWorkOrdersBoard(input) {
  const rows = filterWOs(input.filters || {});
  const limit = input.limit || 50;
  const fields = input.fields || ["Deal name masked", "Customer Name Code", "Sector", "Execution Status", "Amount in Rupees (Excl of GST) (Masked)", "Billed Value in Rupees (Excl of GST.) (Masked)", "Collected Amount in Rupees (Incl of GST.) (Masked)", "Amount to be billed in Rs. (Exl. of GST) (Masked)", "WO Status (billed)", "Collection status"];
  const result = rows.slice(0, limit).map(r => {
    const out = {};
    fields.forEach(f => { if (r[f] !== undefined) out[f] = r[f]; });
    return out;
  });
  const totalWOValue = rows.reduce((s, r) => { const v = parseNum(r["Amount in Rupees (Excl of GST) (Masked)"]); return v ? s + v : s; }, 0);
  const totalBilled = rows.reduce((s, r) => { const v = parseNum(r["Billed Value in Rupees (Excl of GST.) (Masked)"]); return v ? s + v : s; }, 0);
  const totalCollected = rows.reduce((s, r) => { const v = parseNum(r["Collected Amount in Rupees (Incl of GST.) (Masked)"]); return v ? s + v : s; }, 0);
  const totalToBill = rows.reduce((s, r) => { const v = parseNum(r["Amount to be billed in Rs. (Exl. of GST) (Masked)"]); return v ? s + v : s; }, 0);
  return { total_rows: rows.length, returned: result.length, financial_summary: { total_wo_value: Math.round(totalWOValue), total_billed: Math.round(totalBilled), total_collected: Math.round(totalCollected), total_to_bill: Math.round(totalToBill), billing_rate_pct: totalWOValue ? Math.round(totalBilled / totalWOValue * 100) : null, collection_rate_pct: totalBilled ? Math.round(totalCollected / totalBilled * 100 * 1.18) : null }, rows: result };
}

function aggregateDealsBoard(input) {
  const rows = filterDeals(input.filters || {});
  const groupBy = input.group_by || "Sector/service";
  const valueField = input.value_field || "Masked Deal value";
  return { total_rows: rows.length, group_by: groupBy, value_field: valueField, aggregation: aggregateField(rows, groupBy, valueField) };
}

function aggregateWorkOrdersBoard(input) {
  const rows = filterWOs(input.filters || {});
  const groupBy = input.group_by || "Sector";
  const valueField = input.value_field || "Amount in Rupees (Excl of GST) (Masked)";
  return { total_rows: rows.length, group_by: groupBy, value_field: valueField, aggregation: aggregateField(rows, groupBy, valueField) };
}

function getDataQualityReport() {
  const dealNullValues = Object.fromEntries(
    ["Deal Status","Deal Stage","Sector/service","Masked Deal value","Owner code","Tentative Close Date","Closure Probability"]
    .map(f => [f, DEALS_RAW.filter(r => !r[f]).length])
  );
  const woNullValues = Object.fromEntries(
    ["Execution Status","Sector","Amount in Rupees (Excl of GST) (Masked)","Billed Value in Rupees (Excl of GST.) (Masked)","WO Status (billed)","Collection status"]
    .map(f => [f, WO_RAW.filter(r => !r[f]).length])
  );
  return {
    deals_board: { total_rows: DEALS_RAW.length, null_counts: dealNullValues, notes: ["Deal values are masked (scaled by a factor)", "Some rows have duplicate headers (cleaned)", "179 deals have null monetary values"] },
    work_orders_board: { total_rows: WO_RAW.length, null_counts: woNullValues, notes: ["Amounts are masked/scaled", "WO Status and Collection Status have many nulls", "Execution Status is generally complete"] },
    cross_board: { notes: ["Deals and Work Orders share masked deal names and owner codes", "Sector naming is consistent across boards"] }
  };
}

function executeTool(name, input) {
  try {
    switch(name) {
      case "query_deals_board": return queryDealsBoard(input);
      case "query_work_orders_board": return queryWorkOrdersBoard(input);
      case "aggregate_deals_board": return aggregateDealsBoard(input);
      case "aggregate_work_orders_board": return aggregateWorkOrdersBoard(input);
      case "get_data_quality_report": return getDataQualityReport();
      default: return { error: "Unknown tool: " + name };
    }
  } catch(e) { return { error: e.message }; }
}

